def min_cost_to_palindrome(N, strings):
    # Dictionary to store the frequency of each character
    char_count = {}

    # Count the frequency of each character in all strings
    for s, c in strings:
        for char in s:
            if char in char_count:
                char_count[char] += c
            else:
                char_count[char] = c

    # Check if it's possible to form a palindrome
    for count in char_count.values():
        if count % 2 != 0:
            return -1

    # Calculate the minimum cost
    min_cost = 0
    for count in char_count.values():
        min_cost += count // 2 * min(strings[char_count[char]].cost for char, strings in strings.items() if strings.count(char) == count)

    return min_cost

