def min_cost_to_form_palindrome(N, strings):
    # Initialize a table to store the minimum cost for substrings
    dp = [[float('inf')] * (N + 1) for _ in range(N + 1)]

    # Base case: cost to form a palindrome of length 0 is 0
    for i in range(N + 1):
        dp[i][i] = 0

    # Fill the dp table
    for length in range(2, N + 1):
        for start in range(N - length + 1):
            end = start + length - 1
            if is_palindrome(strings[start][end]):
                dp[start][end] = 0
            else:
                for mid in range(start, end):
                    dp[start][end] = min(dp[start][end], dp[start][mid] + dp[mid + 1][end] + len(strings[start][end]) * strings[start][end])

    # The minimum cost to form a palindrome using all strings
    result = float('inf')
    for i in range(N):
        result = min(result, dp[0][N] + len(strings[i]) * strings[i])

    return result if result != float('inf') else -1

