def min_cost_to_form_palindrome(N, strings):
    # Initialize the DP table
    dp = [float('inf')] * (N + 1)
    dp[0] = 0  # Base case: zero cost to form a palindrome with zero strings

    for i in range(1, N + 1):
        s, c = strings[i - 1]
        n = len(s)

        # Try all possible lengths for the first half
        for j in range(n // 2 + 1):
            # Check if the first j characters match the last n-j characters
            if s[:j] == s[n - j:]:
                # Calculate the cost for using the first j characters
                cost = c * (n - 2 * j + 1) if n % 2 == 1 else c * (n - 2 * j)
                # Update the DP table
                dp[i] = min(dp[i], dp[i - j] + cost)

    # If dp[N] is still infinity, it means no palindrome can be formed
    return dp[N] if dp[N] != float('inf') else -1

