def min_cost_to_palindrome(N, strings):
    # Initialize the DP table
    dp = [[float('inf')] * N for _ in range(N)]

    # Base case: single character strings
    for i in range(N):
        dp[i][i] = strings[i][1]

    # Fill the DP table
    for length in range(2, N + 1):
        for i in range(N - length + 1):
            j = i + length - 1
            if strings[i][0] == strings[j][0]:
                dp[i][j] = dp[i + 1][j - 1] + strings[i][1]
            else:
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    # Check if a palindrome can be formed
    min_cost = float('inf')
    for i in range(N):
        if dp[0][i] != float('inf'):
            min_cost = min(min_cost, dp[0][i])

    return min_cost if min_cost != float('inf') else -1

