def is_valid_sequence(A, B, n):
    # Initialize the elevator state
    elevator_state = [0] * (2 * n + 1)

    # Try to assign floors to each person
    def backtrack(person):
        if person == n:
            return True

        for floor in range(A[person], B[person]):
            if elevator_state[floor] == 0:
                # Place the person on the elevator
                elevator_state[floor] += 1

                # Check if the current configuration is valid
                if is_valid_configuration(elevator_state, person):
                    if backtrack(person + 1):
                        return True

                # Remove the person from the elevator
                elevator_state[floor] -= 1

        return False

    def is_valid_configuration(elevator_state, person):
        # Calculate C_i
        C_i = 0
        for floor in range(1, 2 * n + 1):
            if elevator_state[floor] > 1:
                C_i += 1

        # Check if all C_i are equal
        for floor in range(1, 2 * n + 1):
            if elevator_state[floor] > 0:
                if C_i != C(floor, elevator_state):
                    return False

        return True

    def C(floor, elevator_state):
        count = 0
        for i in range(1, 2 * n + 1):
            if elevator_state[i] > 0 and i != floor:
                count += 1
        return count

    return backtrack(0)

