    visited = [False] * (N + 1)
    stack = [False] * (N + 1)
    for i in range(1, N + 1):
        if not visited[i]:
            if has_cycle(i, visited, stack):
                return -1

    # Topological sort to find the order of players
    def topological_sort():
        visited = [False] * (N + 1)
        result = []

        def dfs(node):
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    dfs(neighbor)
            result.append(node)

        for i in range(1, N + 1):
            if not visited[i]:
                dfs(i)

        return result[::-1]

    # Perform topological sort
    order = topological_sort()

    # Calculate the minimum number of days required
    min_days = 0
    for i in range(1, N + 1):
        if order[i - 1] == i:
