def floyd_warshall(graph):
    n = len(graph)
    dist = [[float('inf')] * n for _ in range(n)]

    # Initialize the distance matrix with edge weights
    for u in range(n):
        for v in range(n):
            if u == v:
                dist[u][v] = 0
            elif graph[u][v]:
                dist[u][v] = graph[u][v]

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist

