    """Compute the binomial coefficient nCk modulo mod."""
    if k > n:
        return 0
    num = 1
    den = 1
    for i in range(k):
        num = (num * (n - i)) % mod
        den = (den * (i + 1)) % mod
    return (num * mod_inverse(den, mod)) % mod

