def can_assign_coordinates(N, M, edges):
    # Build the graph
    graph = defaultdict(list)
    for L, R, D in edges:
        graph[L].append((R, D))

    # Check for cycles using DFS
    visited = [False] * (N + 1)
    rec_stack = [False] * (N + 1)

    def has_cycle(node):
        if rec_stack[node]:
            return True
        if visited[node]:
            return False

        visited[node] = True
        rec_stack[node] = True

        for neighbor, _ in graph[node]:
            if has_cycle(neighbor):
                return True

        rec_stack[node] = False
        return False

    # Find if there is any cycle
    for i in range(1, N + 1):
        if not visited[i] and has_cycle(i):
            return "No"

    # Topological sort to assign coordinates
    indegree = [0] * (N + 1)
    for node in range(1, N + 1):
        for neighbor, _ in graph[node]:
            indegree[neighbor] += 1

    queue = deque([i for i in range(1, N + 1) if indegree[i] == 0])
    coordinates = [-1] * (N + 1)

    while queue:
        node = queue.popleft()
        coordinates[node] = len(queue)

        for neighbor, _ in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all information is satisfied
    for L, R, D in edges:
        if coordinates[R] - coordinates[L] != D:
            return "No"

    return "Yes"

