def can_assign_coordinates(N, M, edges):
    # Build the adjacency list representation of the graph
    graph = defaultdict(list)
    for L, R, D in edges:
        graph[L].append((R, D))

    # Function to detect cycles using DFS
    def dfs(node, visited, stack):
        visited[node] = True
        stack[node] = True

        for neighbor, _ in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, stack):
                    return True
            elif stack[neighbor]:
                return True

        stack[node] = False
        return False

    # Check for cycles
    visited = [False] * (N + 1)
    stack = [False] * (N + 1)
    for i in range(1, N + 1):
        if not visited[i]:
            if dfs(i, visited, stack):
                return "No"

    # If no cycles, perform topological sorting
    in_degree = [0] * (N + 1)
    for u in range(1, N + 1):
        for v, _ in graph[u]:
            in_degree[v] += 1

    queue = deque([i for i in range(1, N + 1) if in_degree[i] == 0])

    coordinates = [0] * (N + 1)
    while queue:
        node = queue.popleft()
        coordinates[node] = len(queue)

        for neighbor, _ in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return "Yes" if all(coordinates[i] >= coordinates[j] + d for i, j, d in edges) else "No"

