    rootX = find(x, parent)
    rootY = find(y, parent)
    if rootX == rootY:
        return False
    if rank[rootX] > rank[rootY]:
        parent[rootY] = rootX
    elif rank[rootX] < rank[rootY]:
        parent[rootX] = rootY
    else:
        parent[rootY] = rootX
