def kruskal(graph):
    edges = sorted(graph.items(), key=lambda item: item[1])
    parent = {node: node for node in graph}
    mst_weight = 0
    mst_edges = []

    for edge in edges:
        u, v, weight = edge
        if find(parent, u) != find(parent, v):
            union(parent, u, v)
            mst_weight += weight
            mst_edges.append((u, v, weight))

    # Check for cycles
    for u, v, _ in mst_edges:
        if find(parent, u) == find(parent, v):
            return -1

    return mst_weight

