from collections import deque

def can_make_choices(N, A, B, C):
    if A < 0 or B < 0 or C < 0:
        return "No"

    # Directions for each choice
    directions = {
        'AB': [(A + 1, B - 1, C), (A - 1, B + 1, C)],
        'AC': [(A + 1, B, C - 1), (A - 1, B, C + 1)],
        'BC': [(A, B + 1, C - 1), (A, B - 1, C + 1)]
    }

    queue = deque([(A, B, C, [])])

    while queue:
        A, B, C, path = queue.popleft()

        if len(path) == N:
            return "Yes", path

        for s in ['AB', 'AC', 'BC']:
            new_A, new_B, new_C = directions[s][0] if directions[s][0][0] >= 0 else directions[s][1]
            if new_A >= 0 and new_B >= 0 and new_C >= 0:
                queue.append((new_A, new_B, new_C, path + [s]))

    return "No"

