def process_queries(N, Q):
    # Initialize the grid
    grid = [[0] * N for _ in range(N)]

    # Place initial black stones
    for i in range(1, N-1):
        for j in range(1, N-1):
            grid[i][j] = 1

    # Place initial white stones on the bottom and right sides
    for i in range(N-1):
        grid[N-1][i] = 2
    for j in range(N-1):
        grid[j][N-1] = 2

    # Process each query
    for _ in range(Q):
        query = input().split()
        query_type = int(query[0])
        x = int(query[1]) - 1  # Convert to 0-based index

        # Place a white stone on the specified position
        if query_type == 1:
            grid[x][0] = 2
        elif query_type == 2:
            grid[0][x] = 2

        # Replace black stones based on the new white stone
        if query_type == 1:
            # Move down from (x, 0)
            for i in range(x+1, N):
                if grid[i][0] == 1:
                    grid[i][0] = 2
                else:
                    break
        elif query_type == 2:
            # Move right from (0, x)
            for j in range(x+1, N):
                if grid[0][j] == 1:
                    grid[0][j] = 2
                else:
                    break

        # Count the number of black stones
        black_stones = sum(sum(row) for row in grid)

    return black_stones

