def lca(u, v, adj, parent):
    if u == v:
        return u
    if parent[u] == v or parent[v] == u:
        return parent[u]
    anc_u = lca(parent[u], v, adj, parent)
    anc_v = lca(parent[v], u, adj, parent)
    if anc_u == anc_v:
        return anc_u
    return anc_u if anc_u != -1 else anc_v

