        else:  # s[i-1] == 'x'
            dp[i][0] = dp[i-1][1]
            dp[i][1] = dp[i-1][0]

    # Check if a valid assignment exists
    if dp[N-1][0] + dp[N-1][1] == 0:
        return -1

    # Construct the final assignment
    assignment = []
    for i in range(N):
        if dp[i][0] >= dp[i][1]:
            assignment.append('S')
        else:
            assignment.append('W')

