def sieve_of_eratosthenes(max_num):
    """Generate a list of prime numbers up to max_num using the Sieve of Eratosthenes."""
    is_prime = [True] * (max_num + 1)
    p = 2
    while (p * p <= max_num):
        if (is_prime[p] == True):
            for i in range(p * p, max_num + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, max_num + 1) if is_prime[p]]
    return prime_numbers

def count_similar_numbers(l, r, primes):
    """Count the number of odd numbers x in the range [l, r] such that both x and (x+1)/2 are prime."""
    count = 0
    for x in range(l, r + 1, 2):  # Iterate over odd numbers only
        if x % 2 == 0 or x > r or (x + 1) // 2 >= r:  # Skip even numbers and out-of-range checks
            continue
        if primes[x] and primes[(x + 1) // 2]:
            count += 1
    return count

