def can_rearrange(A, B):
    N = len(A)

    # Check if A and B are identical
    if A == B:
        return False

    # Check if A and B differ by more than one element
    diff_count = sum(1 for a, b in zip(A, B) if a != b)
    if diff_count > 1:
        return False

    # If A and B differ by exactly one element, swap them
    if diff_count == 1:
        index = next(i for i, (a, b) in enumerate(zip(A, B)) if a != b)
        B[index], B[index + 1] = B[index + 1], B[index]
        return True

    # If A and B differ by more than one element, find a pattern
    # We can alternate between elements of B and elements not in A
    for i in range(N):
        if A[i] == B[i]:
            # Find a replacement for A[i] in B
            for j in range(i + 1, N):
                if B[j] != A[i]:
                    # Swap B[i] and B[j]
                    B[i], B[j] = B[j], B[i]
                    return True
    return False

