def can_reorder(A, B):
    n = len(A)

    # Check if all elements in A are the same
    if len(set(A)) == 1:
        # Check if B has distinct elements
        if len(set(B)) == n:
            return True, B
        else:
            return False, None

    # Find mismatches
    mismatches = []
    for i in range(n):
        if A[i] != B[i]:
            mismatches.append(i)

    # If there are no mismatches, return True and B
    if not mismatches:
        return True, B

    # Try to find a valid permutation
    # Since A and B are sorted, we can try to swap elements
    # to ensure no element matches its corresponding element in A
    # This is a brute-force approach, but it works within the constraints

    def backtrack(start):
        nonlocal B
        if start == n:
            return True

        for i in range(start, n):
            if B[i] == A[start]:
                continue
            B[i], B[start] = B[start], B[i]
            if backtrack(start + 1):
                return True
            B[i], B[start] = B[start], B[i]

        return False

    if backtrack(0):
        return True, B

    return False, None

