from collections import defaultdict

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    pq = [(0, start)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def can_place_signposts(N, M, edges):
    # Build the graph
    graph = defaultdict(dict)
    for u, v in edges:
        graph[u][v] = 1
        graph[v][u] = 1

    # Calculate shortest paths from Room 1
    distances = dijkstra(graph, 1)

    # Check if a valid signpost placement exists
    for i in range(2, N + 1):
        min_distance = float('inf')
        best_room = None

        for j in range(1, N + 1):
            if j != i and distances[j] < min_distance:
                min_distance = distances[j]
                best_room = j

        # If no valid signpost can be placed, return "No"
        if best_room is None:
            return "No"

    # If a valid signpost placement exists, return "Yes" and the signpost for each room
    return "Yes\n" + "\n".join(str(best_room) for best_room in range(2, N + 1))

