    graph = defaultdict(list)

    # Build the graph
    for A, B in passages:
        graph[A].append(B)
        graph[B].append(A)

    # Perform topological sort
    topological_order = topological_sort(graph)

    if not topological_order:
        return "No"

    # Print "Yes" and the topological order
    print("Yes")
    for room in topological_order:
        print(room)

