def topo_sort(graph):
    n = len(graph)
    indegree = [0] * n
    queue = deque()

    # Calculate in-degrees
    for u in range(n):
        for v in graph[u]:
            indegree[v] += 1

    # Initialize the queue with nodes having zero in-degree
    for u in range(n):
        if indegree[u] == 0:
            queue.append(u)

    topological_order = []

    while queue:
        u = queue.popleft()
        topological_order.append(u)

        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    return topological_order

