        while i < len(slopes) and slopes[i] <= a:
            i += 1

        # Update the slopes and intercepts
        if i == 0:
            slopes.insert(0, a)
            intercepts.insert(0, b)
        elif i == len(slopes):
            slopes.append(a)
            intercepts.append(b)
        else:
            slopes[i] = a
            intercepts[i] = b

