import sys

def build_tree(arr, tree, node, start, end):
    if start == end:
        tree[node] = arr[start]
        return
    mid = (start + end) // 2
    build_tree(arr, tree, 2 * node + 1, start, mid)
    build_tree(arr, tree, 2 * node + 2, mid + 1, end)
    tree[node] = min(tree[2 * node + 1], tree[2 * node + 2])

def update_tree(tree, node, start, end, idx, val):
    if start == end:
        tree[node] = val
        return
    mid = (start + end) // 2
    if idx <= mid:
        update_tree(tree, 2 * node + 1, start, mid, idx, val)
    else:
        update_tree(tree, 2 * node + 2, mid + 1, end, idx, val)
    tree[node] = min(tree[2 * node + 1], tree[2 * node + 2])

def query_tree(tree, node, start, end, left, right):
    if left > end or right < start:
        return float('inf')
    if left <= start and end <= right:
        return tree[node]
    mid = (start + end) // 2
    left_min = query_tree(tree, 2 * node + 1, start, mid, left, right)
    right_min = query_tree(tree, 2 * node + 2, mid + 1, end, left, right)
    return min(left_min, right_min)

