class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def update(self, idx, val):
        idx += self.n - 1
        self.tree[idx] += val
        while idx > 0:
            idx //= 2
            self.tree[idx] += val

    def query(self, l, r):
        return self._query(l, r, 0, 0, self.n - 1)

    def _query(self, l, r, idx, tl, tr):
        if l > tr or r < tl:
            return 0
        if l <= tl and r >= tr:
            return self.tree[idx]
        mid = (tl + tr) // 2
        return self._query(l, r, 2 * idx + 1, tl, mid) + self._query(l, r, 2 * idx + 2, mid + 1, tr)

