class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)
        self.lazy = [0] * (4 * n)

    def _push(self, i, l, r):
        if self.lazy[i]:
            self.tree[i] += self.lazy[i] * (r - l + 1)
            if l != r:
                self.lazy[2 * i] += self.lazy[i]
                self.lazy[2 * i + 1] += self.lazy[i]
            self.lazy[i] = 0

    def _update(self, i, l, r, ql, qr, val):
        self._push(i, l, r)
        if l > qr or r < ql:
            return
        if ql <= l and r <= qr:
            self.tree[i] += val * (r - l + 1)
            if l != r:
                self.lazy[2 * i] += val
                self.lazy[2 * i + 1] += val
            return
        mid = (l + r) // 2
        self._update(2 * i, l, mid, ql, qr, val)
        self._update(2 * i + 1, mid + 1, r, ql, qr, val)
        self.tree[i] = min(self.tree[2 * i], self.tree[2 * i + 1])

    def update(self, a, b, val):
        self._update(1, 0, self.n - 1, a, b, val)

    def _query(self, i, l, r, ql, qr):
        self._push(i, l, r)
        if l > qr or r < ql:
            return float('inf'), None
        if ql <= l and r <= qr:
            return self.tree[i], l
        mid = (l + r) // 2
        left_min, left_x = self._query(2 * i, l, mid, ql, qr)
        right_min, right_x = self._query(2 * i + 1, mid + 1, r, ql, qr)
        if left_min < right_min:
            return left_min, left_x
        else:
            return right_min, right_x

    def query(self):
        return self._query(1, 0, self.n - 1, 0, self.n - 1)

