def construct_matrix(N, S, T, U, V):
    # Edge case 1: All U_i = 0 or V_j = 0
    if any(u == 0 for u in U) or any(v == 0 for v in V):
        return '0\n' * N

    # Edge case 2: All U_i = 2^64 - 1 and all V_j = 2^64 - 1
    if all(u == (2**64 - 1) for u in U) and all(v == (2**64 - 1) for v in V):
        return '1\n' * N

    # Construct the matrix
    matrix = [[0] * N for _ in range(N)]

    # Fill the matrix based on conditions
    for i in range(N):
        if S[i] == 0:
            matrix[i] = [u] * N
        else:
            matrix[i] = [1] * N

    for j in range(N):
        if T[j] == 0:
            for i in range(N):
                matrix[i][j] &= V[j]
        else:
            for i in range(N):
                matrix[i][j] |= V[j]

    # Convert the matrix to a string format
    result = '\n'.join(' '.join(str(a) for a in row) for row in matrix)
    return result

