def backtrack(grid, colors_used, colors_remaining, index):
    if index == N:
        return True

    for i in range(H):
        for j in range(W):
            if grid[i][j] == -1:
                for color in colors_remaining:
                    if colors_used[color] < colors_remaining[color]:
                        grid[i][j] = color
                        colors_used[color] += 1
                        if backtrack(grid, colors_used, colors_remaining, index + 1):
                            return True
                        grid[i][j] = -1
                        colors_used[color] -= 1

    return False

