def find_unbalanced_substring(s):
    if not s:
        return "-1 -1"

    n = len(s)
    if n < 2:
        return "-1 -1"

    freq = {}
    max_freq = 0
    left = 0

    for right in range(n):
        char = s[right]
        freq[char] = freq.get(char, 0) + 1
        max_freq = max(max_freq, freq[char])

        # Check if the current window is unbalanced
        if (right - left + 1) // 2 < max_freq:
            continue

        # Shrink the window from the left
        while (right - left + 1) // 2 >= max_freq:
            char = s[left]
            freq[char] -= 1
            if freq[char] == 0:
                del freq[char]
            max_freq = max(freq.values())
            left += 1

        # If we found an unbalanced substring, print the indices
        if (right - left + 1) // 2 < max_freq:
            return f"{left + 1} {right + 1}"

    return "-1 -1"

# Read input from standard input
input_string = input().strip()

